-- drizzle cannot model: touch triggers, RLS policies, grants.
-- Sections (touch triggers, RLS) are the verbatim output of ./generate-platform-sql.ts.

-- touch-updated-at: generated by @seta/shared-db buildTouchUpdatedAtFnSql/buildTouchTriggerSql
CREATE OR REPLACE FUNCTION integrations.tg_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END $$;
CREATE TRIGGER m365_group_links_touch_updated_at
BEFORE UPDATE ON integrations.m365_group_links
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();
CREATE TRIGGER m365_subscriptions_touch_updated_at
BEFORE UPDATE ON integrations.m365_subscriptions
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();
CREATE TRIGGER m365_plan_links_touch_updated_at
BEFORE UPDATE ON integrations.m365_plan_links
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();
CREATE TRIGGER m365_resource_etags_touch_updated_at
BEFORE UPDATE ON integrations.m365_resource_etags
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();
CREATE TRIGGER m365_tenant_config_touch_updated_at
BEFORE UPDATE ON integrations.m365_tenant_config
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();
CREATE TRIGGER mail_transport_config_touch_updated_at
BEFORE UPDATE ON integrations.mail_transport_config
FOR EACH ROW EXECUTE FUNCTION integrations.tg_touch_updated_at();

